const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'..');
const table=(caption,headers,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${caption}"><table><caption>${caption}</caption><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const sections={
 '국비지원-훈련과정-선택-가이드': `<h2>수강료가 싼 과정과 실제 부담이 적은 과정은 다릅니다</h2><p>아래는 비교 방법을 보여주기 위해 임의로 만든 두 과정입니다. 실제 학원의 가격, 평균 비용, 고용24의 자비부담 산정 결과가 아닙니다. 두 과정의 자격·수업내용·실습시간이 본인 목표에 맞는다는 전제에서만 비용을 비교합니다.</p>${table('가상 과정의 총현금지출 비교',['항목','가상 과정 A','가상 과정 B'],[['결제할 수강료','100,000원','180,000원'],['교통비','5,000원 × 40일 = 200,000원','3,000원 × 20일 = 60,000원'],['별도 재료비','150,000원','50,000원'],['합계','450,000원','290,000원']])}<p>A의 수강료는 8만원 저렴하지만 위 가정의 총지출은 B보다 16만원 많습니다. 이 예시에는 식비, 시험 응시료, 추가 연습비와 결석에 따른 비용을 넣지 않았습니다. 장려금은 선정·출석 등 조건을 확인하기 전까지 확정 수입으로 빼지 마세요.</p><h2>훈련기관에 같은 질문으로 견적을 받으세요</h2>${table('수강신청 전 비교 기록표',['적을 내용','과정 A','과정 B'],[['과정명·공식 과정 URL·조회일','직접 기록','직접 기록'],['본인 자비부담금·추가 재료비·별도 실습비','기관의 답변과 포함 항목 기록','같은 항목으로 확인'],['실제 장비 사용시간·1대당 인원','직접 기록','직접 기록'],['통학일수·왕복 시간·교통비','직접 계산','직접 계산'],['취소·환불·중도탈락 안내 확인 위치','규정의 링크 또는 문서명','규정의 링크 또는 문서명']])}<p>온라인으로 확인한 금액과 상담 답변이 다르면 과정 회차, 본인 유형과 비용 포함 범위가 같은지 확인합니다. 최종 조건을 확인하기 전에는 이 표의 예시 금액으로 결제 여부를 결정하지 마세요.</p>`,
 '4050-재취업-자격증-고르는-기준': `<h2>자격증 이름보다 지원 가능한 공고부터 비교하세요</h2><p>다음 표는 독자가 직접 채우는 편집부 작성용 양식입니다. 아래 상황은 실제 구인공고나 취업 성공 사례가 아니라 판단 순서를 설명하는 가상 예시입니다. 같은 자격증이라도 근무시간, 경력, 운전·체력 조건에 따라 지원할 공고가 달라집니다.</p>${table('같은 자격증을 준비하는 두 사람의 다른 선택',['가상 상황','먼저 확인할 조건','교육 결제 전에 할 일'],[['야간 근무가 어려운 사람','공고에 적힌 교대·야간·당직 일정','주간 공고를 모으고 필수 자격을 다시 분류'],['관련 업무 경험은 있지만 자격이 없는 사람','자격이 필수인지 우대인지, 경력 증빙 방법','현재 지원 가능한 공고와 자격 취득 뒤 가능한 공고 구분'],['관련 경험이 없는 초보자','신입 지원 여부·단독 업무·인수인계 조건','수료가 경력을 대체하는지 임의로 가정하지 않고 채용처에 질문']])}<h2>공고 세 개를 같은 항목으로 기록하는 양식</h2>${table('자격증 결제 전 공고 대조표',['확인 항목','공고 1','공고 2','공고 3'],[['공고 URL·확인일·마감일','직접 기록','직접 기록','직접 기록'],['필수 자격 / 우대 자격','구분해서 기록','구분해서 기록','구분해서 기록'],['경력·근무시간·당직·이동 조건','직접 기록','직접 기록','직접 기록'],['현재 충족 / 교육으로 보완 / 교육으로 해결 불가','세 범주로 분류','세 범주로 분류','세 범주로 분류']])}<p>지원할 수 없는 이유가 근무시간이나 필수 경력이라면 자격을 하나 더 따는 것만으로 해결되지 않을 수 있습니다. 반대로 여러 관심 공고에 같은 필수 자격이 반복된다면 그 자격의 시험·훈련비를 조사할 근거가 됩니다. 공고 세 개는 준비 연습을 위한 편집 제안이지 지역 채용시장 전체를 대표하는 표본이 아닙니다.</p>`,
 '4050-자격증-로드맵': `<h2>8주 계획은 확보 가능한 시간으로 역산하세요</h2><p>아래는 주당 6시간을 8주간 확보한 사람의 가상 계획입니다. 총 48시간은 특정 시험의 합격에 필요한 시간이나 공식 권장시간이 아닙니다. 본인의 기초 수준, 공개문제, 실습 가능 날짜를 확인해 늘리거나 줄여야 합니다.</p>${table('주당 6시간을 확보한 경우의 가상 준비 배분',['기간','계획 시간','남겨야 할 결과물'],[['1주차','6시간','목표 공고·필수 자격·시험요건·예산 확인표'],['2~4주차','18시간','학습 범위별 오답과 실습 가능한 기관 목록'],['5~6주차','12시간','제한시간을 정한 연습 결과와 부족 항목'],['7주차','6시간','부족 항목 재연습·접수 및 준비물 확인'],['8주차','6시간','마무리 점검과 다음 회차로 넘길 항목 결정']])}<p>하루 30분씩 평일 다섯 번은 2시간 30분이지 5시간이 아닙니다. 여기에 주말 3시간 30분을 더해야 주당 6시간이 됩니다. 통근시간의 영상 시청과 장비가 필요한 실습시간을 같은 방식으로 계산하지 마세요.</p><h2>접수일 전에 계획을 바꿔야 하는 경우</h2><ul><li>작업형 실습 예약이 불가능하면 필기 진도만으로 실기 준비가 끝났다고 판단하지 않습니다.</li><li>필수 응시자격이 충족되지 않았다면 공부 진도보다 자격 확인이 먼저입니다.</li><li>예산이 부족하면 수강료뿐 아니라 교통·재료·추가 연습비를 다시 합산합니다.</li><li>공고의 근무조건이 맞지 않으면 이미 공부했다는 이유만으로 같은 진로를 고집하지 않습니다.</li></ul><p>미뤄야 할 때는 다음 회차의 접수 가능 여부를 공식 일정에서 확인하고, 유지할 학습과 중단할 결제를 구분하세요. 이 계획표는 합격을 보장하는 학습 처방이 아니라 준비 누락을 찾는 도구입니다.</p>`
};
for(const [slug,body] of Object.entries(sections)){
 const file=path.join(root,slug,'index.html');let html=fs.readFileSync(file,'utf8');
 const section=`<!-- decision-worksheet:start -->\n${body}\n<!-- decision-worksheet:end -->\n`;
 if(html.includes('<!-- decision-worksheet:start -->'))html=html.replace(/<!-- decision-worksheet:start -->[\s\S]*?<!-- decision-worksheet:end -->\s*/,section);
 else {const marker=html.match(/<h2[^>]*>[^<]*(?:자주 묻는 질문|FAQ)[^<]*<\/h2>/)?.[0];if(!marker)throw new Error('Missing FAQ '+slug);html=html.replace(marker,section+marker);}
 if(!html.includes('/assets/editorial.css'))html=html.replace('</head>','<link rel="stylesheet" href="/assets/editorial.css?v=20261019">\n</head>');
 html=html.replace(/("dateModified"\s*:\s*")[^"]+"/g,'$12026-10-19"')
  .replace(/(내용 확인 )\d{4}-\d{2}-\d{2}/g,'$12026-10-19')
  .replace(/(<dt>업데이트<\/dt>\s*<dd>)[^<]+/g,'$12026년 10월 19일');
 fs.writeFileSync(file,html);
 console.log('Added decision worksheet '+slug);
}
